const now = new Date();
const dayOfWeek = now.getDay();
const days = ['Domingo', 'Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado'];
const dayName = days[dayOfWeek];

let contentType;
if (dayOfWeek === 0) {
  contentType = 'resumo_semanal';
} else if ([1, 2, 4, 6].includes(dayOfWeek)) {
  contentType = 'editorial';
} else {
  contentType = 'promocional';
}

return [{
  json: {
    contentType,
    dayName,
    dayOfWeek,
    timestamp: now.toISOString(),
    executionId: $execution.id
  }
}];

const allItems = $input.all();
const normalized = [];
const seenUrls = new Set();

for (const item of allItems) {
  const d = item.json;
  let entries = [];

  // Itens RSS
  if (d.title && d.link) {
    entries.push({
      titulo: d.title,
      url_fonte: d.link,
      fonte: d.creator || d.source || 'RSS',
      fonte_tipo: 'rss',
      resumo_bruto: d.contentSnippet || d.content || d.description || '',
      data_noticia: d.isoDate || d.pubDate || new Date().toISOString()
    });
  }

  // Resultados do Perplexity - formato HTTP Request (choices[0].message.content)
  if (d.choices && d.choices[0] && d.choices[0].message) {
    try {
      const parsed = JSON.parse(d.choices[0].message.content);
      const arr = Array.isArray(parsed) ? parsed : (parsed.news || parsed.articles || [parsed]);
      for (const a of arr) {
        entries.push({
          titulo: a.title || a.titulo || '',
          url_fonte: a.url || a.link || '',
          fonte: a.source || a.fonte || 'Perplexity',
          fonte_tipo: 'perplexity',
          resumo_bruto: a.summary || a.resumo || '',
          data_noticia: a.date || a.data || new Date().toISOString()
        });
      }
    } catch (e) {}
  }

  // Resultados do Perplexity nativo (n8n-nodes-base.perplexity)
  // O node nativo retorna: { content: "...", model: "...", ... } ou { message: { content: "..." } }
  if (d.content && typeof d.content === 'string' && !d.title && !d.choices) {
    try {
      const parsed = JSON.parse(d.content);
      const arr = Array.isArray(parsed) ? parsed : (parsed.news || parsed.articles || [parsed]);
      for (const a of arr) {
        entries.push({
          titulo: a.title || a.titulo || '',
          url_fonte: a.url || a.link || '',
          fonte: a.source || a.fonte || 'Perplexity',
          fonte_tipo: 'perplexity',
          resumo_bruto: a.summary || a.resumo || '',
          data_noticia: a.date || a.data || new Date().toISOString()
        });
      }
    } catch (e) {}
  }

  // Resultados do SerpAPI
  if (d.news_results && Array.isArray(d.news_results)) {
    for (const n of d.news_results) {
      entries.push({
        titulo: n.title || '',
        url_fonte: n.link || '',
        fonte: n.source?.name || n.source || 'Google News',
        fonte_tipo: 'serpapi',
        resumo_bruto: n.snippet || '',
        data_noticia: n.date || new Date().toISOString()
      });
    }
  }

  // Resultados do SerpAPI (formato alternativo: organic_results do Google News)
  if (d.organic_results && Array.isArray(d.organic_results)) {
    for (const n of d.organic_results) {
      entries.push({
        titulo: n.title || '',
        url_fonte: n.link || '',
        fonte: n.source || 'Google News',
        fonte_tipo: 'serpapi',
        resumo_bruto: n.snippet || '',
        data_noticia: n.date || new Date().toISOString()
      });
    }
  }

  // Itens de newsletters Gmail (pré-normalizados pelo Parse Gmail News)
  if (d.fonte_tipo === 'gmail' && d.titulo) {
    entries.push({
      titulo: d.titulo,
      url_fonte: d.url_fonte || '',
      fonte: d.fonte || 'Newsletter Gmail',
      fonte_tipo: 'gmail',
      resumo_bruto: d.resumo_bruto || '',
      data_noticia: d.data_noticia || new Date().toISOString()
    });
  }

  for (const entry of entries) {
    const key = entry.url_fonte || entry.titulo;
    if (key && !seenUrls.has(key)) {
      seenUrls.add(key);
      normalized.push({ json: entry });
    }
  }
}

return normalized.length > 0 ? normalized : [{ json: { error: 'Nenhum artigo encontrado', timestamp: new Date().toISOString() } }];

const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  try {
    const curation = JSON.parse(item.json.choices[0].message.content);
    const score_total = (curation.score_impacto * 0.30) + (curation.score_novidade * 0.25) + (curation.score_relevancia * 0.30) + (curation.score_engajamento * 0.15);

    results.push({
      json: {
        ...($('Normalize Data').all()[i]?.json || {}),
        score_impacto: curation.score_impacto,
        score_novidade: curation.score_novidade,
        score_relevancia: curation.score_relevancia,
        score_engajamento: curation.score_engajamento,
        score_total: Math.round(score_total * 100) / 100,
        categoria: curation.categoria,
        palavras_chave: curation.palavras_chave,
        motivo: curation.motivo
      }
    });
  } catch (e) {
    // skip items that fail to parse
  }
}

results.sort((a, b) => b.json.score_total - a.json.score_total);
return results;

