const seoRaw = $('AI SEO').item.json.choices[0].message.content;
const editor = JSON.parse(editorRaw);
const seo = JSON.parse(seoRaw);
const articleId = $('Select Best Article').item.json.id;

const esc = (s) => (s || '').replace(/'/g, "''");

const query = `UPDATE ai_news SET
  titulo = '${esc(editor.titulo)}',
  conteudo_blog = '${esc(editor.conteudo_blog)}',
  conteudo_resumo = '${esc(editor.conteudo_resumo)}',
  ponto_vista_intellix = '${esc(editor.ponto_vista_intellix)}',
  tempo_leitura = '${esc(String(editor.tempo_leitura))}',
  meta_title = '${esc(seo.meta_title)}',
  meta_description = '${esc(seo.meta_description)}',
  slug = '${esc(seo.slug)}',
  keywords = '${esc(JSON.stringify(seo.keywords))}',
  legenda_instagram = '${esc(seo.legenda_instagram)}',
  hashtags = '${esc(JSON.stringify(seo.hashtags))}',
  qualidade_aprovada = ${editor.qualidade_aprovada || false},
  status = 'revisao'
WHERE id = '${articleId}'`;

return [{ json: { query, articleId } }];

const articleId = $('Save Final Content').item.json.articleId;
const titulo = $('Select Best Article').item.json.titulo;

const prompt = `Professional tech blog cover image. Theme: ${titulo}. Style: Futuristic minimalist, deep indigo (#1e1b4b), electric purple (#6366f1), warm amber (#f59e0b). Abstract tech elements, neural patterns. No text, no people. HD quality.`;

return [{ json: { prompt, articleId, titulo } }];

const items = $input.all();
const articleId = $('Generate Image Prompt').item.json.articleId;
let imageUrl = '';
let isFallback = false;

for (const item of items) {
  // Try DALL-E result
  if (item.json.data && item.json.data[0] && item.json.data[0].url) {
    imageUrl = item.json.data[0].url;
    break;
  }
  // Try Unsplash result
  if (item.json.results && item.json.results[0] && item.json.results[0].urls) {
    imageUrl = item.json.results[0].urls.regular;
    isFallback = true;
    break;
  }
}

if (!imageUrl) {
  imageUrl = 'https://intellix.ai/placeholder-cover.jpg';
  isFallback = true;
}

return [{ json: { articleId, imageUrl, isFallback } }];

// Prepara dados do carrossel a partir do artigo
const article = $('Fetch Final Article').item.json;

// Monta legenda
let caption = article.legenda_instagram || article.conteudo_resumo || '';
const cta = '\n\n🔗 Link na bio para ler o artigo completo!\n\n';
const fixedHashtags = '#InteligenciaArtificial #IA #AutomacaoInteligente #IntelliXAI #TechBrasil';
let articleHashtags = '';
try {
  const tags = JSON.parse(article.hashtags || '[]');
  articleHashtags = tags.map(t => t.startsWith('#') ? t : '#' + t).join(' ');
} catch (e) { articleHashtags = ''; }

let fullCaption = caption + cta + articleHashtags + ' ' + fixedHashtags;
if (fullCaption.length > 2200) {
  fullCaption = fullCaption.substring(0, 2197) + '...';
}

// Extrai palavras-chave para busca de imagens no Unsplash
let keywords = [];
try {
  keywords = JSON.parse(article.keywords || '[]');
} catch (e) { keywords = []; }

// Seleciona 4 palavras-chave diversas para slides do carrossel
const searchTerms = [];
if (keywords.length >= 4) {
  searchTerms.push(keywords[0], keywords[1], keywords[2], keywords[3]);
} else {
  const titleWords = (article.titulo || 'inteligência artificial tecnologia').split(' ')
    .filter(w => w.length > 3);
  for (let i = 0; i < 4; i++) {
    searchTerms.push(keywords[i] || titleWords[i] || ['inteligência artificial', 'aprendizado de máquina', 'ciência de dados', 'inovação digital'][i]);
  }
}

return [{
  json: {
    caption: fullCaption,
    coverImageUrl: article.imagem_feed_url || article.imagem_url || '',
    articleId: article.id,
    titulo: article.titulo,
    searchTerms: searchTerms,
    igAccountId: '1176594747652660'
  }
}];

const raw = $('AI Promo Writer').item.json.choices[0].message.content;
const content = JSON.parse(raw);
const articleId = $('Insert Promo as News').item.json.id;

const esc = (s) => (s || '').replace(/'/g, "''");

const query = `UPDATE ai_news SET
  titulo = '${esc(content.titulo)}',
  conteudo_blog = '${esc(content.conteudo_blog)}',
  conteudo_resumo = '${esc(content.conteudo_resumo)}',
  ponto_vista_intellix = '${esc(content.ponto_vista_intellix)}',
  meta_title = '${esc(content.meta_title)}',
  meta_description = '${esc(content.meta_description)}',
  slug = '${esc(content.slug)}',
  legenda_instagram = '${esc(content.legenda_instagram)}',
  hashtags = '${esc(JSON.stringify(content.hashtags))}',
  tempo_leitura = '${esc(String(content.tempo_leitura))}',
  status = 'revisao'
WHERE id = '${articleId}'`;

return [{ json: { query, articleId } }];

const articles = $input.all();
const now = new Date();
const weekStart = new Date(now);
weekStart.setDate(now.getDate() - 7);

const articleIds = articles.map(a => a.json.id).filter(Boolean);
const topArticles = articles.slice(0, 5);

const summaryData = {
  semana_inicio: weekStart.toISOString().split('T')[0],
  semana_fim: now.toISOString().split('T')[0],
  total_artigos: articles.length,
  top_article_ids: JSON.stringify(articleIds.slice(0, 5)),
  articles: topArticles.map(a => ({
    titulo: a.json.titulo,
    categoria: a.json.categoria,
    score: a.json.score_total
  }))
};

return [{ json: summaryData }];

const raw = $('AI Summary Writer').item.json.choices[0].message.content;
const content = JSON.parse(raw);
const summaryData = $('Insert Weekly Summary').item.json;

const esc = (s) => (s || '').replace(/'/g, "''");

const query = `INSERT INTO weekly_summary (semana_inicio, semana_fim, total_artigos, top_article_ids, titulo_resumo, introducao, conteudo_resumo, conclusao, ponto_vista_semanal, legenda_instagram, carrossel_slides, hashtags, meta_title, meta_description, slug, status) VALUES ('${summaryData.semana_inicio}', '${summaryData.semana_fim}', ${summaryData.total_artigos}, '${esc(summaryData.top_article_ids)}', '${esc(content.titulo_resumo)}', '${esc(content.introducao)}', '${esc(content.conteudo_resumo)}', '${esc(content.conclusao)}', '${esc(content.ponto_vista_semanal)}', '${esc(content.legenda_instagram)}', '${esc(JSON.stringify(content.carrossel_slides))}', '${esc(JSON.stringify(content.hashtags))}', '${esc(content.meta_title)}', '${esc(content.meta_description)}', '${esc(content.slug)}', 'agendado')`;

return [{ json: { query } }];

// ===========================================
// NEWSLETTERS BRASILEIRAS DE TECH/IA PARA MONITORAR
// Adicione ou remova endereços conforme necessário
// ===========================================
const senders = [
  // --- Newsletters brasileiras de tecnologia ---
  'newsletter@startse.com',
  'contato@startse.com.br',
  'inventormiguel@substack.com>'
  // --- Newsletters de IA/dados em português ---

  // --- Newsletters internacionais de IA (referência) ---

];

const query = 'from:(' + senders.join(' OR ') + ') newer_than:1d';
return [{ json: { searchQuery: query, senders, senderCount: senders.length } }];

const emails = $input.all();
const articles = [];
const seen = new Set();

for (const email of emails) {
  const e = email.json;
  const subject = e.subject || '';
  const from = (e.from && typeof e.from === 'object' && e.from.value && e.from.value[0])
    ? e.from.value[0].address
    : (typeof e.from === 'string' ? e.from : 'Unknown');
  const date = e.date || e.internalDate || new Date().toISOString();
  const body = e.textPlain || e.snippet || '';
  const html = e.textHtml || '';

  const urlRegex = /https?:\/\/[^\s<>"'\)\]]+/g;
  const allUrls = (html || body).match(urlRegex) || [];

  const articleUrls = allUrls.filter(function(url) {
    var lower = url.toLowerCase();
    return lower.indexOf('unsubscribe') === -1 &&
           lower.indexOf('manage-preferences') === -1 &&
           lower.indexOf('click.') === -1 &&
           lower.indexOf('tracking') === -1 &&
           lower.indexOf('beacon') === -1 &&
           lower.indexOf('mailchimp') === -1 &&
           lower.indexOf('list-manage') === -1 &&
           lower.indexOf('emailoctopus') === -1 &&
           lower.indexOf('convertkit') === -1 &&
           url.length < 300;
  });

  var uniqueUrls = [];
  var urlPaths = new Set();
  for (var u of articleUrls) {
    try {
      var parsed = new URL(u);
      var key = parsed.hostname + parsed.pathname;
      if (!urlPaths.has(key)) { urlPaths.add(key); uniqueUrls.push(u); }
    } catch(ex) {}
  }

  if (uniqueUrls.length > 0) {
    for (var url of uniqueUrls.slice(0, 5)) {
      if (!seen.has(url)) {
        seen.add(url);
        articles.push({ json: {
          titulo: subject,
          url_fonte: url,
          fonte: from,
          fonte_tipo: 'gmail',
          resumo_bruto: body.substring(0, 800),
          data_noticia: date
        }});
      }
    }
  } else if (subject && !seen.has(subject)) {
    seen.add(subject);
    articles.push({ json: {
      titulo: subject,
      url_fonte: 'gmail://' + (e.id || Date.now()),
      fonte: from,
      fonte_tipo: 'gmail',
      resumo_bruto: body.substring(0, 800),
      data_noticia: date
    }});
  }
}

return articles.length > 0
  ? articles
  : [{ json: { titulo: '', url_fonte: '', fonte: 'gmail', fonte_tipo: 'gmail', resumo_bruto: '', data_noticia: new Date().toISOString() } }];

// Gera 4 itens, um por palavra-chave para busca no Unsplash
const data = $input.first().json;
const terms = data.searchTerms || ['inteligência artificial', 'aprendizado de máquina', 'ciência de dados', 'inovação digital'];

return terms.map((term, i) => ({
  json: {
    searchTerm: term,
    slideIndex: i + 1,
    coverImageUrl: data.coverImageUrl,
    caption: data.caption,
    articleId: data.articleId,
    titulo: data.titulo
  }
}));

// Coleta todos os resultados do Unsplash + imagem de capa no formato carrossel
const unsplashResults = $input.all();

// URL da imagem de capa (DALL-E/Unsplash)
const coverUrl = $('Prepare Carousel Keywords').first().json.coverImageUrl;
const caption = $('Prepare Carousel Keywords').first().json.caption;
const articleId = $('Prepare Carousel Keywords').first().json.articleId;

// Monta array de itens do carrossel
const items = [];

// Slide 1: Imagem de capa do DALL-E/Unsplash (imagem principal do artigo)
items.push({
  json: {
    image_url: coverUrl,
    slideIndex: 0,
    isCover: true,
    caption: caption,
    articleId: articleId
  }
});

// Slides 2-5: Imagens do Unsplash
for (const result of unsplashResults) {
  const photos = result.json.results || [];
  if (photos.length > 0) {
    // Usa tamanho regular (1080w) para Instagram
    const url = photos[0].urls.regular || photos[0].urls.small;
    items.push({
      json: {
        image_url: url,
        slideIndex: items.length,
        isCover: false,
        caption: caption,
        articleId: articleId
      }
    });
  }
}

// Garante mínimo de 2 itens (mínimo para carrossel)
if (items.length < 2) {
  return [items[0]];
}

return items;

// Coleta todos os IDs de upload para criar o container do carrossel
const uploads = $input.all();
const childrenIds = uploads.map(u => u.json.id).filter(Boolean);
const caption = $('Build Carousel Items').first().json.caption;
const articleId = $('Build Carousel Items').first().json.articleId;

// Se só tem 1 item, será post simples (não carrossel)
const isCarousel = childrenIds.length >= 2;

return [{
  json: {
    children: childrenIds,
    childrenString: childrenIds.join(','),
    caption: caption,
    articleId: articleId,
    isCarousel: isCarousel,
    mediaCount: childrenIds.length
  }
}];

