      titulo: subject,
      url_fonte: 'gmail://' + (e.id || Date.now()),
      fonte: from,
      fonte_tipo: 'gmail',
      resumo_bruto: body.substring(0, 800),
      data_noticia: date
    }});
  }
}

return articles.length > 0
