items.push({
  json: {
    image_url: coverUrl,
    slideIndex: 0,
    isCover: true,
    caption: caption,
    articleId: articleId
  }
});

// Slides 2-5: Imagens do Unsplash
for (const result of unsplashResults) {
  const photos = result.json.results || [];
  if (photos.length > 0) {
    // Usa tamanho regular (1080w) para Instagram
    const url = photos[0].urls.regular || photos[0].urls.small;
    items.push({
      json: {
        image_url: url,
        slideIndex: items.length,
        isCover: false,
        caption: caption,
        articleId: articleId
      }
    });
  }
}

// Garante mínimo de 2 itens (mínimo para carrossel)
if (items.length < 2) {
  return [items[0]];
}

return items;

// Coleta todos os IDs de upload para criar o container do carrossel
const uploads = $input.all();
const childrenIds = uploads.map(u => u.json.id).filter(Boolean);
const caption = $('Build Carousel Items').first().json.caption;
const articleId = $('Build Carousel Items').first().json.articleId;

// Se só tem 1 item, será post simples (não carrossel)
const isCarousel = childrenIds.length >= 2;

return [{
